            if ((i * n + j) % 20 == 0)
                fprintf(stderr, "\n");
            fprintf(stderr, "%0.6lf ", Q[i][j]);
        }
    fprintf(stderr, "\nend   dump: %s\n", "Q");
    fprintf(stderr, "==END   DUMP_ARRAYS==\n");
}

int main() {

    int m = 20;
    int n = 30;

    double A[20][30];
    double R[30][30];
    double Q[20][30];

    init_array(m, n, A, R, Q);

    kernel_gramschmidt(A, R, Q);

    print_array(m, n, A, R, Q);

    return 0;
}
