        // Update: subtract the projection of remaining columns onto q_k
        for (int j = k + 1; j < N; j++) {
            double dot = 0.0;
            for (int i = 0; i < M; i++) {
                dot += Q[i][k] * A[i][j];
            }
            R[k][j] = dot;

            for (int i = 0; i < M; i++) {
                A[i][j] -= dot * Q[i][k];
            }
        }
    }
